-- Tanda UniX/SEO: tipo «Humanoides y cuadrúpedos», FAQ/especificaciones EN, alt de galería y enlaces del artículo.
--
-- El tipo «robots-recepcion-atencion» dejaba los UniX como «Robots de recepción y atención».
-- atributos se fusiona (||): no borra otras claves. Los UPDATE del artículo solo actúan si el ancla existe y el enlace aún no está.
-- Requiere que la familia «robots» exista en public.familias.
--
-- NO aplicar a producción sin OK explícito.

INSERT INTO public.tipos (familia_id, slug, nombre_es, nombre_en, orden, activo)
SELECT f.id, 'robots-humanoides-cuadrupedos', 'Humanoides y cuadrúpedos', 'Humanoid and quadruped robots', 20, true
FROM public.familias f
WHERE f.slug = 'robots'
ON CONFLICT (familia_id, slug) DO NOTHING;

UPDATE public.productos
   SET tipo_id = (SELECT t.id FROM public.tipos t JOIN public.familias f ON f.id = t.familia_id
                   WHERE f.slug = 'robots' AND t.slug = 'robots-humanoides-cuadrupedos'),
       atributos = atributos || $ime_attrs${"preguntas_frecuentes_en":[{"q":"What is the price?","a":"No price is published. The quote is confirmed per project with I-ME, including configuration and installation scope."},{"q":"Is it a medical device?","a":"No. It is a service humanoid robot. The manufacturer material does not present it as a medical device."},{"q":"Where is the technical sheet?","a":"The manufacturer’s official sheet in English is available for download on this page."}],"especificaciones_en":[{"grupo":"System","clave":"Total degrees of freedom","valor":"23 DoF"},{"grupo":"System","clave":"Dimensions (L × W × H)","valor":"527 mm × 620 mm × 1680 mm"},{"grupo":"System","clave":"Minimum passage width","valor":"75 cm"},{"grupo":"Head","clave":"Head field of view","valor":"Yaw ±90°, Pitch ±30°"},{"grupo":"Head","clave":"Head cameras","valor":"HD Stereo Camera ×1 + Orbbec Gemini 2 Camera ×1"},{"grupo":"Bionic arm","clave":"DoF per arm","valor":"8 DoF"},{"grupo":"Bionic arm","clave":"Load for both arms","valor":"12 kg"},{"grupo":"Bionic arm","clave":"Reach of one arm","valor":"982 mm"},{"grupo":"Bionic arm","clave":"End effector","valor":"Two-finger adaptive gripper"},{"grupo":"Torso","clave":"Torso lift height","valor":"280 mm"},{"grupo":"Safety","clave":"Emergency stop","valor":"Physical / wireless"},{"grupo":"Functions","clave":"Voice interaction","valor":"Compatible with multiple LLMs (e.g. DeepSeek)"},{"grupo":"Compute","clave":"Compute platform","valor":"NVIDIA Jetson Orin NX 16G (100 TOPS)"},{"grupo":"Battery","clave":"Charging time","valor":"~2 h"},{"grupo":"Battery","clave":"Runtime","valor":"8–16 h"},{"grupo":"Mobility","clave":"Maximum speed","valor":"1.5 m/s"},{"grupo":"Mobility","clave":"Navigation sensors","valor":"LiDAR ×1"},{"grupo":"Mobility","clave":"Drive","valor":"Differential with two hub motors"},{"grupo":"Mobility","clave":"RGB-D camera","valor":"Orbbec 336 RGB-D Camera"},{"grupo":"Mobility","clave":"Obstacle height it can clear","valor":"≤ 20 mm"},{"grupo":"Teleoperation","clave":"VR teleoperation device","valor":"quest3S"}],"galeria_alt_es":["UniX Wanda 2.0 Pro, robot humanoide: imagen 1 de 3","UniX Wanda 2.0 Pro, robot humanoide: imagen 2 de 3","UniX Wanda 2.0 Pro, robot humanoide: imagen 3 de 3"],"galeria_alt_en":["UniX Wanda 2.0 Pro humanoid robot: image 1 of 3","UniX Wanda 2.0 Pro humanoid robot: image 2 of 3","UniX Wanda 2.0 Pro humanoid robot: image 3 of 3"],"imagen_ancho":1600,"imagen_alto":900}$ime_attrs$::jsonb
 WHERE slug = 'unix-wanda-2-0-pro-robot-humanoide-ref-wanda-2-0-pro-unix';

