:"Intelligence","clave":"Autonomous navigation","valor":"Optional"},{"grupo":"Intelligence","clave":"Obstacle avoidance","valor":"Standard"},{"grupo":"Communication","clave":"WiFi / Bluetooth","valor":"Standard"},{"grupo":"Communication","clave":"Cellular","valor":"4G"},{"grupo":"Communication","clave":"Interfaces","valor":"Gigabit Ethernet ×2, USB 3.0 ×2, RS232 ×1, RS485 ×1, SBUS ×2, PPS ×1"},{"grupo":"Communication","clave":"Real-time image transmission","valor":"Standard"},{"grupo":"Accessories","clave":"Battery","valor":"15,000 mAh"},{"grupo":"Accessories","clave":"Remote control","valor":"No screen"},{"grupo":"Accessories","clave":"Charging station with autonomous return","valor":"Optional"}],"galeria_alt_es":["UniX Pioneer H, robot cuadrúpedo industrial: imagen 1 de 1"],"galeria_alt_en":["UniX Pioneer H industrial quadruped robot: image 1 of 1"],"imagen_ancho":836,"imagen_alto":585}$ime_attrs$::jsonb
