UPDATE public.articulos
   SET cuerpo_es = replace(cuerpo_es, $ime_articulo$El encaje depende del **mapa del edificio**, protocolos de seguridad y el rol exacto que se quiere automatizar.$ime_articulo$, $ime_articulo$El encaje depende del **mapa del edificio**, protocolos de seguridad y el rol exacto que se quiere automatizar.

Para comparar modelos por categoría, consulte la [familia de robots](/es/familias/robots/). Entre los humanoides publicados, el [UniX Wanda 2.0 Pro](/es/productos/unix-wanda-2-0-pro-robot-humanoide-ref-wanda-2-0-pro-unix/) tiene como aplicaciones publicadas la recepción y la guía, y el [UniX Panther Pro](/es/productos/unix-panther-pro-robot-humanoide-ref-panther-pro-unix/) las rondas de seguridad y la atención en tienda. Ninguno se presenta como dispositivo médico.$ime_articulo$)
 WHERE slug = 'robots-asistenciales-atencion-reduccion-carga-personal'
   AND position($ime_articulo$El encaje depende del **mapa del edificio**, protocolos de seguridad y el rol exacto que se quiere automatizar.$ime_articulo$ in cuerpo_es) > 0
   AND position($ime_articulo$/es/familias/robots/$ime_articulo$ in cuerpo_es) = 0;

UPDATE public.articulos
   SET cuerpo_en = replace(cuerpo_en, $ime_articulo$Fit depends on **building maps**, safety protocols and the exact role to automate.$ime_articulo$, $ime_articulo$Fit depends on **building maps**, safety protocols and the exact role to automate.

To compare models by category, see the [robot family](/en/families/robots/). Among the published humanoids, the [UniX Wanda 2.0 Pro](/en/products/unix-wanda-2-0-pro-robot-humanoide-ref-wanda-2-0-pro-unix/) lists reception and guidance as published applications, and the [UniX Panther Pro](/en/products/unix-panther-pro-robot-humanoide-ref-panther-pro-unix/) lists security rounds and store assistance. Neither is presented as a medical device.$ime_articulo$)
 WHERE slug = 'robots-asistenciales-atencion-reduccion-carga-personal'
   AND position($ime_articulo$Fit depends on **building maps**, safety protocols and the exact role to automate.$ime_articulo$ in cuerpo_en) > 0
   AND position($ime_articulo$/en/families/robots/$ime_articulo$ in cuerpo_en) = 0;
